class Solution {
public:
    int assignBikes(vector<vector<int>>& workers, vector<vector<int>>& bikes) {
        int n = workers.size(), m = bikes.size();
        vector<vector<int>> memo(n, vector<int>(1 << m, -1));

        auto dfs = [&](auto& self, int w, int mask) -> int {
            if (w == n) return 0;
            if (memo[w][mask] != -1) return memo[w][mask];
            int res = 1e9;
            for (int b = 0; b < m; ++b) {
                if (!(mask & (1 << b))) {
                    int d = abs(workers[w][0] - bikes[b][0]) + abs(workers[w][1] - bikes[b][1]);
                    res = min(res, d + self(self, w + 1, mask | (1 << b)));
                }
            }
            return memo[w][mask] = res;
        };

        return dfs(dfs, 0, 0);
    }
};

class Solution {
    public int assignBikes(int[][] workers, int[][] bikes) {
        int n = workers.length, m = bikes.length;
        int[][] memo = new int[n][1 << m];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dfs(workers, bikes, 0, 0, n, m, memo);
    }

    private int dfs(int[][] workers, int[][] bikes, int w, int mask, int n, int m, int[][] memo) {
        if (w == n) return 0;
        if (memo[w][mask] != -1) return memo[w][mask];
        int res = Integer.MAX_VALUE / 2;
        for (int b = 0; b < m; ++b) {
            if ((mask & (1 << b)) == 0) {
                int d = Math.abs(workers[w][0] - bikes[b][0]) + Math.abs(workers[w][1] - bikes[b][1]);
                res = Math.min(res, d + dfs(workers, bikes, w + 1, mask | (1 << b), n, m, memo));
            }
        }
        return memo[w][mask] = res;
    }
}

var assignBikes = function(workers, bikes) {
    const n = workers.length, m = bikes.length;
    const memo = new Map();

    const dfs = (w, mask) => {
        if (w === n) return 0;
        const key = (w << 10) | mask;
        if (memo.has(key)) return memo.get(key);
        let res = Infinity;
        const [wx, wy] = workers[w];
        for (let b = 0; b < m; b++) {
            if (!(mask & (1 << b))) {
                const d = Math.abs(wx - bikes[b][0]) + Math.abs(wy - bikes[b][1]);
                res = Math.min(res, d + dfs(w + 1, mask | (1 << b)));
            }
        }
        memo.set(key, res);
        return res;
    };

    return dfs(0, 0);
};
